{% extends "base.html" %}
{% block title %}BNI{{ chapter.name_zh }}{% endblock %}
{% block body %}

{% if chapter.status == 'forming' %}
<div class="placeholder-note">籌備中・尚未在BNI Connect正式登記</div>
{% endif %}

<header>
  <div class="wrap navbar">
    <a class="logo" href="/">BNI {{ chapter.name_zh }}<span>{{ chapter.name_en or '' }}・大台南南區</span></a>
    <nav class="main-nav"><ul>
      <li><a href="/">分會列表</a></li>
      <li><a href="#about">認識分會</a></li>
      <li><a href="#value">核心價值</a></li>
      {% if spirit %}<li><a href="#glory">分會精神</a></li>{% elif stats %}<li><a href="#glory">分會之光</a></li>{% endif %}
      <li><a href="#members">分會夥伴</a></li>
      {% if chapter.show_traditions %}<li><a href="#traditions">六項傳統與道德規範</a></li>{% endif %}
    </ul></nav>
    <div class="nav-actions">
      <button class="hamburger-btn" onclick="openUsefulLinksModal()" aria-label="常用連結" title="常用連結">
        <span></span><span></span><span></span>
      </button>
      <a href="{{ url_for('founder_signup_form', slug=chapter.slug) if chapter.status == 'forming' else '#' }}" class="btn">{{ chapter.cta_label or '預約參訪' }}</a>
    </div>
  </div>
</header>

<div class="hero">
  <div class="wrap">
    {% if chapter.badge_text %}<div class="badge">{{ chapter.badge_text }}</div>{% endif %}
    <h1>{{ chapter.hero_title or chapter.name_zh }}</h1>
    <p>{{ chapter.hero_desc or '' }}</p>
    <div class="cta-row">
      <a href="{{ url_for('founder_signup_form', slug=chapter.slug) if chapter.status == 'forming' else '#' }}" class="btn btn-outline">{{ chapter.cta_label or '預約參訪' }}</a>
    </div>
  </div>
</div>

{% if notices %}
<section id="about">
  <div class="wrap">
    <div class="section-tag">{{ chapter.about_tag or 'Before You Visit' }}</div>
    <h2>{{ chapter.about_title or '參訪須知' }}</h2>
    <p class="lead">{{ chapter.about_desc or '' }}</p>
    <div class="notice-grid">
      {% for n in notices %}
      <div class="notice-card"><div class="notice-num">{{ loop.index }}</div><h3>{{ n.title }}</h3><p>{{ n.body|safe }}</p></div>
      {% endfor %}
    </div>
  </div>
</section>
{% endif %}

<section class="value" id="value">
  <div class="wrap">
    <div class="section-tag">Our Core Value</div>
    <h2>BNI 核心價值</h2>
    <div class="value-grid">
      {% for v in values %}
      <div class="value-card">
        <h3>{{ v.title }}</h3>
        <p>{{ v.body }}</p>
      </div>
      {% endfor %}
    </div>
  </div>
</section>

{% if spirit %}
<section class="spirit-section" id="glory">
  <div class="wrap">
    <div class="section-tag">Chapter Spirit</div>
    <h2>分會精神</h2>
    <div class="spirit-grid">
      {% for v in spirit %}
      <div class="spirit-card"><h3>{{ v.title }}</h3>{% if v.body %}<p>{{ v.body }}</p>{% endif %}</div>
      {% endfor %}
    </div>
  </div>
</section>
{% elif stats %}
<section class="glory" id="glory">
  <div class="wrap">
    <div class="section-tag">Chapter Glory</div>
    <h2>分會之光</h2>
    <div class="glory-grid">
      {% for s in stats %}
      <div class="glory-card"><div class="num">{{ s.num }}</div><p>{{ s.label }}</p></div>
      {% endfor %}
    </div>
  </div>
</section>
{% endif %}

<section class="members" id="members">
  <div class="wrap">
    <div class="section-tag">Our Members</div>
    <h2>分會夥伴</h2>
    <p class="lead">每位夥伴自己填寫、送出後立刻上架，歡迎大家建立自己的簡介卡片</p>
    {% if members %}
    <div class="member-grid">
      {% for m in members %}
      <div class="member-card">
        <div class="member-photo"><img src="{{ url_for('static', filename='uploads/' ~ m.photo_filename) }}" alt="{{ m.name }}"></div>
        <div class="member-info">
          <h3>{{ m.name }}</h3>
          <div class="member-subtitle">{{ m.company_title }}{% if m.role_tag %}<br>{{ m.role_tag }}{% endif %}</div>
          <button class="member-bio-btn"
            data-name="{{ m.name }}"
            data-subtitle="{{ m.company_title }}{% if m.role_tag %} ｜ {{ m.role_tag }}{% endif %}"
            data-bio="{{ m.bio }}"
            data-links='{{ member_links(m) | tojson }}'
            onclick="openMemberBio(this)">簡介</button>
        </div>
      </div>
      {% endfor %}
    </div>
    {% else %}
    <p class="lead" style="margin-bottom:0;">還沒有夥伴資料，歡迎成為第一位。</p>
    {% endif %}
    <div class="cta-row" style="margin-top:40px;">
      <a href="{{ url_for('member_join_form', slug=chapter.slug) }}" class="btn">我要建立我的簡介</a>
    </div>
  </div>
</section>

<div class="member-modal-overlay" id="memberBioModal" onclick="if(event.target===this)closeMemberBio()">
  <div class="member-modal">
    <h3 id="memberModalName"></h3>
    <div class="member-modal-subtitle" id="memberModalSubtitle"></div>
    <div class="member-modal-bio" id="memberModalBio"></div>
    <div class="member-modal-contact" id="memberModalContact"></div>
    <button class="member-modal-close-btn" onclick="closeMemberBio()">關閉</button>
  </div>
</div>

{% if chapter.show_traditions %}
<section class="traditions" id="traditions">
  <div class="wrap">
    <div class="section-tag">BNI Foundations</div>
    <h2>六項傳統與道德規範</h2>
    <div class="traditions-columns">
      <div>
        <h3 class="col-title">六項傳統 <span>Six Traditions</span></h3>
        <ol class="tradition-list">
          <li><b>付出者收穫</b><span>Givers Gain</span></li>
          <li><b>教育與培訓</b><span>Education and Training</span></li>
          <li><b>見證</b><span>Testimonials</span></li>
          <li><b>在基礎中保持樂趣</b><span>Keeping the fun in fundamentals</span></li>
          <li><b>人們不在乎你知道多少，直到他們知道你有多在乎</b><span>People don't care about how much you know...</span></li>
          <li><b>言行一致</b><span>Walking the talk</span></li>
        </ol>
      </div>
      <div>
        <h3 class="col-title">道德規範 <span>Code of Ethics</span></h3>
        <ol class="ethics-list">
          <li>「本人將按照本人的報價提供優質的服務。」</li>
          <li>「本人願意以誠信的態度對待分會會員及他們引薦的人士。」</li>
          <li>「本人願意在會員及他們引薦的人士之間，建立良好的商譽與信任。」</li>
          <li>「本人願意對本人所接收到的業務引薦承擔跟進之責任。」</li>
          <li>「本人願意以積極的態度全力支持 BNI 會員。」</li>
          <li>「本人願意遵守本人所屬行業之職業道德規範。」</li>
        </ol>
      </div>
    </div>
  </div>
</section>
{% endif %}

<footer>
  <div class="wrap">
    <div class="foot-row">
      <div class="foot-slogan">{{ chapter.footer_slogan or chapter.name_zh }}</div>
      <div class="foot-links">
        {% for l in links %}<a href="{{ l.url }}" target="_blank" rel="noopener">{{ l.label }}</a>{% endfor %}
      </div>
    </div>
    <div class="copyright">Copyright © 2026 BNI{{ chapter.name_zh }}・大台南南區</div>
  </div>
</footer>

<div class="links-modal-overlay" id="usefulLinksModal" onclick="if(event.target===this)closeUsefulLinksModal()">
  <div class="links-modal-box">
    <button class="links-modal-close" onclick="closeUsefulLinksModal()" aria-label="關閉">&times;</button>
    <div class="links-modal-scroll">
      <div class="links-modal-section">
        <div class="section-tag">Quick Links</div>
        <h2>常用連結</h2>
        <div class="quicklink-grid">
          {% for l in links if l.url != '#' %}
          <a class="quicklink-card" href="{{ l.url }}" target="_blank" rel="noopener">{{ l.label }}</a>
          {% endfor %}
        </div>
      </div>
    </div>
  </div>
</div>

<script>
function openUsefulLinksModal(){
  document.getElementById('usefulLinksModal').classList.add('open');
  document.body.style.overflow='hidden';
}
function closeUsefulLinksModal(){
  document.getElementById('usefulLinksModal').classList.remove('open');
  document.body.style.overflow='';
}

function openMemberBio(btn){
  document.getElementById('memberModalName').textContent = btn.dataset.name;
  document.getElementById('memberModalSubtitle').textContent = btn.dataset.subtitle;
  var bioEl = document.getElementById('memberModalBio');
  bioEl.innerHTML = '';
  btn.dataset.bio.split(/\n\s*\n/).forEach(function(para){
    if (para.trim()) {
      var p = document.createElement('p');
      p.textContent = para.trim();
      bioEl.appendChild(p);
    }
  });
  var contactEl = document.getElementById('memberModalContact');
  contactEl.innerHTML = '';
  JSON.parse(btn.dataset.links || '[]').forEach(function(link){
    var a = document.createElement('a');
    a.href = link.url; a.target = '_blank'; a.rel = 'noopener'; a.textContent = link.label;
    contactEl.appendChild(a);
  });
  document.getElementById('memberBioModal').classList.add('open');
  document.body.style.overflow='hidden';
}
function closeMemberBio(){
  document.getElementById('memberBioModal').classList.remove('open');
  document.body.style.overflow='';
}
</script>

{% endblock %}

